#[test]
fn a_joined_update_refuses_to_write_a_generated_column() {
    let (engine, mut session) = engine();
    parent_child(&engine, &mut session);
    run(
        engine.as_ref(),
        &mut session,
        "ALTER TABLE Child ADD COLUMN shout VARCHAR(40) \
         GENERATED ALWAYS AS (UPPER(note)) STORED",
    );

    for sql in [
        "UPDATE Child c JOIN Parent p ON c.parentId = p.id SET c.shout = 'NO'",
        // Second position: the check used to run only for the first
        // assignment to a table, so this one wrote nothing and said nothing.
        "UPDATE Child c JOIN Parent p ON c.parentId = p.id SET c.note = 'q', c.shout = 'NO'",
    ] {
        let err = engine.execute(&mut session, sql, &[]).unwrap_err();
        assert_eq!(err.code, 3105, "expected 3105 for: {sql}");
    }

    // Nothing was written on the way to either refusal.
    assert_eq!(
        rows(&engine, &mut session, "SELECT note FROM Child ORDER BY id"),
        vec![vec!["a"], vec!["b"], vec!["c"]]
    );
}

#[test]
fn intersect_all_and_except_all_are_multiset_operations() {
    let (engine, mut session) = engine();
    run(
        &engine,
        &mut session,
        "CREATE TABLE Tally (id INTEGER NOT NULL, name VARCHAR(10) NOT NULL, PRIMARY KEY (id))",
    );
    run(
        &engine,
        &mut session,
        "INSERT INTO Tally (id, name) VALUES (1, 'dup'), (2, 'dup'), (3, 'dup'), (4, 'solo')",
    );

    // Three 'dup' rows on the left, two on the right: ALL keeps two, not three.
    let kept = rows(
        &engine,
        &mut session,
        "SELECT name FROM Tally WHERE name = 'dup' \
         INTERSECT ALL \
         SELECT name FROM Tally WHERE id IN (1, 2)",
    );
    assert_eq!(kept, vec![vec!["dup"], vec!["dup"]]);

    // EXCEPT ALL cancels one occurrence per matching right-hand row.
    let left = rows(
        &engine,
        &mut session,
        "SELECT name FROM Tally WHERE name = 'dup' \
         EXCEPT ALL \
         SELECT name FROM Tally WHERE id = 1",
    );
    assert_eq!(left, vec![vec!["dup"], vec!["dup"]]);

    // Without ALL both stay set operations.
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT name FROM Tally WHERE name = 'dup' \
             INTERSECT \
             SELECT name FROM Tally WHERE id IN (1, 2)"
        )
        .len(),
        1
    );
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT name FROM Tally WHERE name = 'dup' \
             EXCEPT \
             SELECT name FROM Tally WHERE id = 1"
        )
        .len(),
        0
    );
}

#[test]
fn a_non_constant_lag_offset_is_refused() {
    // Defaulting a computed offset to 1 answers a different question than the
    // one asked, without saying so.
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);

    let err = engine
        .execute(
            &mut session,
            "SELECT LAG(name, count) OVER (ORDER BY id) FROM Widget",
            &[],
        )
        .unwrap_err();
    assert_eq!(err.code, 1235);

    let err = engine
        .execute(
            &mut session,
            "SELECT LEAD(name, 1, name) OVER (ORDER BY id) FROM Widget",
            &[],
        )
        .unwrap_err();
    assert_eq!(err.code, 1235);

    // A constant offset still works.
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT LAG(name, 1, 'none') OVER (ORDER BY id) FROM Widget"
        ),
        vec![vec!["none"], vec!["alpha"], vec!["beta"]]
    );
}

#[test]
fn dml_modifiers_mysql_refuses_are_refused_here_too() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);
    run(
        &engine,
        &mut session,
        "CREATE TABLE Tag (wid VARCHAR(21), label VARCHAR(20))",
    );
    run(
        &engine,
        &mut session,
        "INSERT INTO Tag VALUES ('a', 'keep')",
    );

    // "The first row" is not defined across a join, so MySQL allows neither
    // modifier on the multi-table forms. Accepting them would have to invent
    // an order the user never asked for.
    for sql in [
        "UPDATE Widget JOIN Tag ON Tag.wid = Widget.id SET count = 1 LIMIT 1",
        "UPDATE Widget JOIN Tag ON Tag.wid = Widget.id SET count = 1 ORDER BY Widget.id",
        "DELETE Widget FROM Widget JOIN Tag ON Tag.wid = Widget.id LIMIT 1",
        "DELETE FROM Widget USING Widget JOIN Tag ON Tag.wid = Widget.id ORDER BY Widget.id",
    ] {
        let err = engine.execute(&mut session, sql, &[]).unwrap_err();
        assert_eq!(err.code, 1235, "expected ER_NOT_SUPPORTED_YET for: {sql}");
    }

    // A LIMIT that is not an exact row count is refused rather than coerced
    // into one. `1.9` truncating to a single row and `'2'` reading as two are
    // the wrong number of rows deleted, quietly.
    for sql in [
        "DELETE FROM Widget LIMIT -1",
        "DELETE FROM Widget LIMIT 'x'",
        "DELETE FROM Widget LIMIT 1.9",
        "DELETE FROM Widget LIMIT '2'",
        "DELETE FROM Widget LIMIT NULL",
        "UPDATE Widget SET count = 1 LIMIT -1",
        "UPDATE Widget SET count = 1 LIMIT 0.5",
    ] {
        let err = engine.execute(&mut session, sql, &[]).unwrap_err();
        assert_eq!(err.code, 1064, "expected a syntax error for: {sql}");
    }

    // An ORDER BY that cannot be resolved is an error, not an ordering of
    // nothing — silently falling back to storage order would let the LIMIT
    // pick an arbitrary row and call it the first.
    for sql in [
        "DELETE FROM Widget ORDER BY nope LIMIT 1",
        "UPDATE Widget SET count = 1 ORDER BY nope LIMIT 1",
    ] {
        let err = engine.execute(&mut session, sql, &[]).unwrap_err();
        assert_eq!(err.code, 1054, "{sql}");
    }

    // RETURNING is still not implemented, and still says so.
    let err = engine
        .execute(&mut session, "DELETE FROM Widget RETURNING id", &[])
        .unwrap_err();
    assert_eq!(err.code, 1235);

    // Every row survived every refusal.
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT count FROM Widget ORDER BY id"
        ),
        vec![vec!["3"], vec!["1"], vec!["2"]]
    );
}

#[test]
fn an_out_of_scope_qualifier_is_an_unknown_column() {
    // The evaluator used to fall back to an unqualified lookup, so a wrong
    // alias bound to another table's same-named column and drove real writes.
    let (engine, mut session) = engine();
    parent_child(&engine, &mut session);

    for sql in [
        "SELECT zz.id FROM Child",
        "UPDATE Child c JOIN Parent p ON c.parentId = p.id SET c.note = 'x' WHERE zz.id = 10",
        "DELETE c FROM Child c JOIN Parent p ON c.parentId = p.id WHERE zz.id = 10",
    ] {
        let err = engine.execute(&mut session, sql, &[]).unwrap_err();
        assert_eq!(err.code, 1054, "expected ER_BAD_FIELD_ERROR for: {sql}");
    }

    assert_eq!(
        rows(&engine, &mut session, "SELECT note FROM Child ORDER BY id"),
        vec![vec!["a"], vec!["b"], vec!["c"]]
    );
}

/// An UPDATE or a DELETE resolves its names before it looks at a row.
///
/// The write half of the hole #0058 closed for SELECT, and the worse half: a
/// name is only resolved when a row is evaluated against it, so over an empty
/// table nothing was resolved and the statement reported nought rows affected.
/// `Affected { rows: 0 }` is exactly what a WHERE that matched nothing looks
/// like, so the caller could not tell "nothing matched" from "the statement was
/// illegal". Every code below was measured on 8.3.
///
/// Every statement here is one where the clause is evaluated for *no* row,
/// which is what a mutation moving the check back into the row path cannot
/// survive: the whole zero-rows checklist — an empty table, `WHERE 1 = 0`,
/// `LIMIT 0` and a CASE branch nothing takes.
#[test]
fn dml_resolves_its_names_even_where_no_row_evaluates_them() {
    let (engine, mut session) = engine();
    for ddl in [
        "CREATE TABLE Bare (id INT NOT NULL, k INT NULL, PRIMARY KEY (id))",
        "CREATE TABLE Other (id INT NOT NULL, q INT NULL, PRIMARY KEY (id))",
        "CREATE TABLE Pop (id INT NOT NULL, s VARCHAR(20) NULL, PRIMARY KEY (id))",
    ] {
        run(&engine, &mut session, ddl);
    }
    run(&engine, &mut session, "INSERT INTO Other VALUES (1, 7)");
    run(&engine, &mut session, "INSERT INTO Pop VALUES (1, 'a')");

    // The clause name is asserted with the code, because it is the half that
    // was wrong even where the statement did refuse: the evaluator reports
    // every unknown name as being in the field list, so `DELETE FROM Pop WHERE
    // nope = 1` over a table with rows in it said `in 'field list'` where 8.3
    // says `in 'where clause'`.
    for (sql, message) in [
        // An empty table, through every clause each of the four entry points
        // reaches. `Bare` has no rows, so nothing evaluates any of these.
        (
            "UPDATE Bare SET k = 1 WHERE a.b = 1",
            "Unknown column 'a.b' in 'where clause'",
        ),
        (
            "UPDATE Bare SET k = 1 WHERE nope = 1",
            "Unknown column 'nope' in 'where clause'",
        ),
        (
            "DELETE FROM Bare WHERE a.b = 1",
            "Unknown column 'a.b' in 'where clause'",
        ),
        (
            "UPDATE Bare SET k = a.b",
            "Unknown column 'a.b' in 'field list'",
        ),
        // A join with an empty side produces no pair of rows, so the joined
        // paths settle their WHERE for no row at all.
        (
            "UPDATE Bare a JOIN Other b ON a.id = b.id SET a.k = 1 WHERE zz.q = 1",
            "Unknown column 'zz.q' in 'where clause'",
        ),
        (
            "UPDATE Bare a JOIN Other b ON a.id = b.id SET a.k = zz.q",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "DELETE a FROM Bare a JOIN Other b ON a.id = b.id WHERE zz.q = 1",
            "Unknown column 'zz.q' in 'where clause'",
        ),
        // The USING spelling of the same statement, which reaches
        // `delete_joined` by the other road.
        (
            "DELETE FROM a USING Bare a JOIN Other b ON a.id = b.id WHERE zz.q = 1",
            "Unknown column 'zz.q' in 'where clause'",
        ),
        // A table that *has* rows, refused for the other three reasons a
        // clause can go unevaluated: a filter nothing survives, a LIMIT of
        // none, and a branch nothing takes.
        (
            "UPDATE Pop SET s = 'x' WHERE 1 = 0 AND a.b = 1",
            "Unknown column 'a.b' in 'where clause'",
        ),
        (
            "DELETE FROM Pop WHERE 1 = 0 AND a.b = 1",
            "Unknown column 'a.b' in 'where clause'",
        ),
        (
            "UPDATE Pop SET s = 'x' WHERE a.b = 1 LIMIT 0",
            "Unknown column 'a.b' in 'where clause'",
        ),
        (
            "DELETE FROM Pop WHERE a.b = 1 LIMIT 0",
            "Unknown column 'a.b' in 'where clause'",
        ),
        (
            "UPDATE Pop SET s = CASE WHEN 0 THEN a.b ELSE 'z' END",
            "Unknown column 'a.b' in 'field list'",
        ),
        // Named without a qualifier, which is the same resolution and a
        // different spelling of the message.
        (
            "DELETE FROM Pop WHERE nope = 1",
            "Unknown column 'nope' in 'where clause'",
        ),
    ] {
        let err = refusal_of(&engine, &mut session, sql);
        assert_eq!(err.code, 1054, "expected ER_BAD_FIELD_ERROR for: {sql}");
        assert_eq!(err.message, message, "for: {sql}");
    }

    // The orderings, each measured on 8.3 rather than assumed.
    for (sql, code, why) in [
        // A missing table comes first, so the guard sits after the table is
        // resolved and not before it.
        (
            "UPDATE nosuch SET k = 1 WHERE a.b = 1",
            1146,
            "1146 is answered before 1054",
        ),
        (
            "DELETE FROM nosuch WHERE a.b = 1",
            1146,
            "1146 is answered before 1054",
        ),
        // The name beats the malformed ESCAPE, which is the ordering #0087
        // recorded as this one's to correct: it answered 1210 here.
        (
            "UPDATE Pop SET s = 'x' WHERE nope = 1 AND s LIKE 'a' ESCAPE '!!'",
            1054,
            "1054 is resolved before 1210",
        ),
        (
            "DELETE FROM Pop WHERE nope = 1 AND s LIKE 'a' ESCAPE '!!'",
            1054,
            "1054 is resolved before 1210",
        ),
        // And the predicate's ESCAPE still beats an unknown assignment
        // target, so the WHERE is settled ahead of the SET either way.
        (
            "UPDATE Pop SET nope = 'x' WHERE s LIKE 'a' ESCAPE '!!'",
            1210,
            "the predicate is settled before the assignment target",
        ),
        // Which tables a multi-table DELETE names is settled before its
        // predicate: 8.3 answers 1066 for the repeated target.
        (
            "DELETE a, a FROM Bare a JOIN Other b ON a.id = b.id WHERE nope = 1",
            1066,
            "1066 is answered before 1054",
        ),
        // A repeated alias in the FROM of a joined UPDATE, likewise.
        (
            "UPDATE Bare a JOIN Bare a ON 1 SET a.k = 1 WHERE nope = 1",
            1066,
            "1066 is answered before 1054",
        ),
    ] {
        let err = refusal_of(&engine, &mut session, sql);
        assert_eq!(err.code, code, "{why}, for: {sql}");
    }

    // Nothing legal now refuses, which is the direction that matters: #0058's
    // first attempt at this resolver rejected a back-quoted qualifier, and
    // only review caught it. A correlated reference is the other trap — it
    // resolves against the enclosing row rather than against the subquery's
    // own FROM, and a walk that descended into the subquery would refuse it.
    for sql in [
        "UPDATE Pop SET s = 'x' WHERE id IN (SELECT id FROM Other WHERE Other.q = Pop.id)",
        "UPDATE Pop SET s = 'x' WHERE EXISTS (SELECT 1 FROM Other o WHERE o.id = Pop.id)",
        "UPDATE Pop SET s = (SELECT 'y' FROM Other o WHERE o.id = Pop.id)",
        "UPDATE Pop p SET p.s = 'x' WHERE p.id = 1",
        "UPDATE `Pop` SET `s` = 'x' WHERE `Pop`.`id` = 1",
        "UPDATE testdb.Pop SET s = 'x' WHERE testdb.Pop.id = 1",
        "UPDATE Pop SET s = 'x' WHERE @@sql_mode IS NOT NULL",
        "UPDATE Pop SET s = 'x' WHERE TIMESTAMPDIFF(DAY, '2026-01-01', '2026-03-05') > 1",
        "DELETE FROM Pop WHERE `Pop`.`id` = 99",
        "DELETE a FROM Pop a JOIN Other b ON a.id = b.id WHERE b.q = 99",
        // `DEFAULT` in a value position parses as an identifier, so a resolver
        // that does not know the keyword reports it as an unknown column and
        // refuses a statement 8.3 accepts. Over the empty table, which is the
        // only shape this engine answers at all: the evaluator has no meaning
        // for the keyword either, so the same statement over rows is still
        // 1054 — a gap of its own, and not one this guard may widen.
        "UPDATE Bare SET k = DEFAULT",
        "UPDATE Bare a JOIN Other b ON a.id = b.id SET a.k = DEFAULT",
    ] {
        run(&engine, &mut session, sql);
    }

    // Every refusal above left the tables as they were, and every legal write
    // above touched only the one row it was aimed at.
    assert!(rows(&engine, &mut session, "SELECT id FROM Bare").is_empty());
    assert_eq!(
        rows(&engine, &mut session, "SELECT id, s FROM Pop ORDER BY id"),
        vec![vec!["1", "x"]]
    );
}

/// 1054 names the clause the reference was written in, not the field list.
///
/// #0099. The evaluator reported every unknown name as being in the field
/// list, because a `Context` carried no clause and `lookup` had a literal in
/// it. The message is the entire product of this path — a client matching on
/// it, or a person reading it, was sent to a clause the name is not in.
///
/// Every string below was measured on 8.3, and two of them are why they were
/// measured rather than derived: GROUP BY is `'group statement'` and not
/// `'group clause'` as every other name would suggest, and a window's two
/// interior clauses have names of their own that neither the field list nor
/// the plain `'order clause'` matches.
///
/// The tables have rows in them on purpose. Refusing these clauses *before* a
/// row reaches them is #0100, which owns every clause not yet resolved at
/// prepare; what is asserted here is the name the refusal carries, so each
/// statement is one that does evaluate the clause.
#[test]
fn a_1054_names_the_clause_the_reference_was_written_in() {
    let (engine, mut session) = engine();
    for ddl in [
        "CREATE TABLE Cl (id INT NOT NULL, k INT NULL, s VARCHAR(20) NULL, PRIMARY KEY (id))",
        "CREATE TABLE Cr (id INT NOT NULL, k INT NULL, PRIMARY KEY (id))",
        "INSERT INTO Cl VALUES (1, 10, 'a'), (2, 20, 'b')",
        "INSERT INTO Cr VALUES (1, 10), (2, 20)",
    ] {
        run(&engine, &mut session, ddl);
    }

    for (sql, message) in [
        // The two that were already right, kept beside the others so a change
        // that reverts the whole mechanism to one name is visible as such.
        (
            "SELECT zz.q FROM Cl",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "SELECT k FROM Cl WHERE zz.q = 1",
            "Unknown column 'zz.q' in 'where clause'",
        ),
        // The six the issue lists.
        (
            "SELECT k FROM Cl GROUP BY zz.q",
            "Unknown column 'zz.q' in 'group statement'",
        ),
        (
            "SELECT k FROM Cl GROUP BY k HAVING zz.q > 1",
            "Unknown column 'zz.q' in 'having clause'",
        ),
        (
            "SELECT k FROM Cl ORDER BY zz.q",
            "Unknown column 'zz.q' in 'order clause'",
        ),
        (
            "SELECT Cl.k FROM Cl JOIN Cr ON zz.q = Cr.id",
            "Unknown column 'zz.q' in 'on clause'",
        ),
        (
            "SELECT SUM(k) OVER (PARTITION BY zz.q) FROM Cl",
            "Unknown column 'zz.q' in 'window partition by'",
        ),
        (
            "SELECT SUM(k) OVER (ORDER BY zz.q) FROM Cl",
            "Unknown column 'zz.q' in 'window order by'",
        ),
        // A LEFT join reports the same clause as an inner one, and so does a
        // condition the engine builds itself from a `USING` list — the list's
        // own names are `'from clause'`, which is the pair below.
        (
            "SELECT Cl.k FROM Cl LEFT JOIN Cr ON zz.q = Cr.id",
            "Unknown column 'zz.q' in 'on clause'",
        ),
        (
            "SELECT Cl.k FROM Cl JOIN Cr USING (zz)",
            "Unknown column 'zz' in 'from clause'",
        ),
        // A DML ORDER BY, which #0100's note measured as `'order clause'`
        // against the `'field list'` this used to answer. The WHERE picks a
        // row, so the clause is evaluated rather than skipped.
        (
            "UPDATE Cl SET k = 1 WHERE id = 1 ORDER BY zz.q LIMIT 1",
            "Unknown column 'zz.q' in 'order clause'",
        ),
        (
            "DELETE FROM Cl WHERE id = 1 ORDER BY zz.q LIMIT 1",
            "Unknown column 'zz.q' in 'order clause'",
        ),
        // Wrapped in a call and in an operator, because MySQL names the
        // position and not the shape of the expression sitting in it.
        (
            "SELECT k FROM Cl GROUP BY ABS(zz.q)",
            "Unknown column 'zz.q' in 'group statement'",
        ),
        (
            "SELECT Cl.k FROM Cl JOIN Cr ON ABS(zz.q) = Cr.id",
            "Unknown column 'zz.q' in 'on clause'",
        ),
        (
            "SELECT SUM(k) OVER (PARTITION BY ABS(zz.q)) FROM Cl",
            "Unknown column 'zz.q' in 'window partition by'",
        ),
        (
            "SELECT SUM(k) OVER (ORDER BY ABS(zz.q)) FROM Cl",
            "Unknown column 'zz.q' in 'window order by'",
        ),
        (
            "SELECT k FROM Cl ORDER BY zz.q + 1",
            "Unknown column 'zz.q' in 'order clause'",
        ),
        // Written without a qualifier, which is a different arm of the
        // evaluator and reaches a different one of the two places the
        // evaluator spells this message: a bare name is reported by the lookup
        // itself, a qualified one by the arm that called it. Reverting either
        // to the field list on its own leaves the other right, so both
        // spellings are asserted for each clause.
        (
            "SELECT k FROM Cl GROUP BY zz",
            "Unknown column 'zz' in 'group statement'",
        ),
        (
            "SELECT Cl.k FROM Cl JOIN Cr ON zz = Cr.id",
            "Unknown column 'zz' in 'on clause'",
        ),
        (
            "SELECT SUM(k) OVER (PARTITION BY zz) FROM Cl",
            "Unknown column 'zz' in 'window partition by'",
        ),
        (
            "SELECT SUM(k) OVER (ORDER BY zz) FROM Cl",
            "Unknown column 'zz' in 'window order by'",
        ),
        (
            "UPDATE Cl SET k = 1 WHERE id = 1 ORDER BY zz LIMIT 1",
            "Unknown column 'zz' in 'order clause'",
        ),
        (
            "DELETE FROM Cl WHERE id = 1 ORDER BY zz LIMIT 1",
            "Unknown column 'zz' in 'order clause'",
        ),
        // A window function's own argument is in the clause the *call* is
        // written in, not in the OVER spec beside it: measured, `SUM(a.b)
        // OVER (ORDER BY b)` is 1054 in the field list on 8.3.
        (
            "SELECT SUM(zz.q) OVER (ORDER BY k) FROM Cl",
            "Unknown column 'zz.q' in 'field list'",
        ),
        // The name follows where the reference is written and not which query
        // level owns the scope. Each of these is a subquery whose own clause
        // is named, and the last two are correlated references to the outer
        // query written in an inner clause — 8.3 names the inner one.
        (
            "SELECT k FROM Cl WHERE id IN (SELECT id FROM Cr GROUP BY zz.q)",
            "Unknown column 'zz.q' in 'group statement'",
        ),
        (
            "SELECT k FROM Cl WHERE id IN (SELECT Cr.id FROM Cr JOIN Cl c2 ON zz.q = c2.id)",
            "Unknown column 'zz.q' in 'on clause'",
        ),
        (
            "SELECT k FROM Cl WHERE Cl.id IN (SELECT Cr.id FROM Cr GROUP BY Cl.zz)",
            "Unknown column 'Cl.zz' in 'group statement'",
        ),
        (
            "SELECT k FROM Cl WHERE Cl.id IN (SELECT Cr.id FROM Cr JOIN Cl c2 ON Cl.zz = c2.id)",
            "Unknown column 'Cl.zz' in 'on clause'",
        ),
        // Which clause is named only matters once they differ, and then it is
        // decided by which one is resolved first. 8.3 reads the select list
        // before the rest of the query body, so with an unresolvable name in
        // two clauses at once the field list wins — measured for each of
        // these. Naming the clauses correctly is what exposed the ordering:
        // while everything said `'field list'` this engine's answer looked
        // right whichever clause it had actually read.
        (
            "SELECT zz.q FROM Cl GROUP BY yy.r",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "SELECT zz.q FROM Cl GROUP BY zz.q",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "SELECT SUM(zz.q) FROM Cl GROUP BY k",
            "Unknown column 'zz.q' in 'field list'",
        ),
        // A GROUP BY that names a select item — by position or by alias —
        // resolves to that item's expression, so the only place the reference
        // is written is the field list and that is what 8.3 names.
        (
            "SELECT zz.q FROM Cl GROUP BY 1",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "SELECT zz.q AS a FROM Cl GROUP BY a",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "SELECT zz.q FROM Cl GROUP BY k HAVING yy.r > 1",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "SELECT zz.q FROM Cl GROUP BY k ORDER BY yy.r",
            "Unknown column 'zz.q' in 'field list'",
        ),
        // The WHERE is behind the select list too, and ahead of the GROUP BY.
        (
            "SELECT zz.q FROM Cl WHERE yy.r = 1",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "SELECT zz.q FROM Cl WHERE yy.r = 1 ORDER BY xx.p",
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "SELECT k FROM Cl WHERE zz.q = 1 GROUP BY yy.r",
            "Unknown column 'zz.q' in 'where clause'",
        ),
        // And where the select list is fine, the GROUP BY still beats the
        // HAVING and the ORDER BY behind it.
        (
            "SELECT k FROM Cl GROUP BY yy.r HAVING xx.p > 1",
            "Unknown column 'yy.r' in 'group statement'",
        ),
        (
            "SELECT k FROM Cl GROUP BY yy.r ORDER BY xx.p",
            "Unknown column 'yy.r' in 'group statement'",
        ),
    ] {
        let err = refusal_of(&engine, &mut session, sql);
        assert_eq!(err.code, 1054, "expected ER_BAD_FIELD_ERROR for: {sql}");
        assert_eq!(err.sql_state, "42S22", "for: {sql}");
        assert_eq!(err.message, message, "for: {sql}");
    }

    // The select list carries more than its names, and all of it is settled
    // ahead of the WHERE and the GROUP BY: 8.3 answers 1210 and 1582 for these
    // rather than the 1054 the other clause would give, and 1051 for a
    // wildcard whose qualifier names nothing.
    for (sql, code) in [
        ("SELECT s LIKE 'a' ESCAPE '!!' FROM Cl GROUP BY zz.q", 1210),
        ("SELECT SIGN() FROM Cl GROUP BY zz.q", 1582),
        ("SELECT nope.* FROM Cl GROUP BY k", 1051),
        ("SELECT s LIKE 'a' ESCAPE '!!' FROM Cl WHERE nope = 1", 1210),
        ("SELECT SIGN() FROM Cl WHERE nope = 1", 1582),
        ("SELECT nope.* FROM Cl WHERE zz.q = 1", 1051),
    ] {
        let err = refusal_of(&engine, &mut session, sql);
        assert_eq!(err.code, code, "for: {sql}");
    }

    // Every refusal above left both tables as they were — the two DML cases
    // included, which is the half a wrong clause name would not have shown.
    assert_eq!(
        rows(&engine, &mut session, "SELECT id, k FROM Cl ORDER BY id"),
        vec![vec!["1", "10"], vec!["2", "20"]]
    );
}

/// The same clauses, refused before a row rather than by one.
///
/// #0100. Every statement in the test above evaluates its clause, because it
/// runs over a table with rows in it. Over an *empty* table the clause was
/// never read at all: a GROUP BY, a join's ON, an OVER spec's two clauses and
/// a DML ORDER BY were all settled once per row, so a query answered an empty
/// set and — far worse — an `UPDATE` whose WHERE matched nothing reported
/// nought rows affected, where 8.3 refuses all of them outright. A caller
/// cannot tell "nothing matched" from "the statement was illegal".
///
/// Measured on 8.3 through the `mysql` crate's `COM_STMT_PREPARE`, which
/// refuses each of these before the statement is executed at all — the CLI
/// never prepares, so the text-protocol probe this repo usually reaches for
/// could not see any of it. This engine refuses a query at prepare too (see
/// `describe.rs`); a DML statement it still prepares and then refuses on
/// execute, because `describe` will not probe a body that writes.
///
/// The clause names are the same strings the test above pins, deliberately
/// asserted again from the other path: the two are settled by different code
/// and a divergence between them is exactly what a client would trip over.
#[test]
fn a_clause_is_refused_over_an_empty_table_rather_than_answered() {
    let (engine, mut session) = engine();
    for ddl in [
        "CREATE TABLE ClE (id INT NOT NULL, k INT NULL, s VARCHAR(20) NULL, PRIMARY KEY (id))",
        "CREATE TABLE CrE (id INT NOT NULL, k INT NULL, PRIMARY KEY (id))",
        // The one table here with a row in it, for the correlated-ON cases at
        // the end: a subquery has to run for its join to be built at all.
        "CREATE TABLE Seed (id INT NOT NULL, k INT NULL, PRIMARY KEY (id))",
        "INSERT INTO Seed VALUES (1, 10)",
    ] {
        run(&engine, &mut session, ddl);
    }

    for (sql, code, message) in [
        (
            "SELECT k FROM ClE GROUP BY zz.q",
            1054,
            "Unknown column 'zz.q' in 'group statement'",
        ),
        (
            "SELECT ClE.k FROM ClE JOIN CrE ON zz.q = CrE.id",
            1054,
            "Unknown column 'zz.q' in 'on clause'",
        ),
        (
            "SELECT ClE.k FROM ClE LEFT JOIN CrE ON zz.q = CrE.id",
            1054,
            "Unknown column 'zz.q' in 'on clause'",
        ),
        (
            "SELECT SUM(k) OVER (PARTITION BY zz.q) FROM ClE",
            1054,
            "Unknown column 'zz.q' in 'window partition by'",
        ),
        (
            "SELECT SUM(k) OVER (ORDER BY zz.q) FROM ClE",
            1054,
            "Unknown column 'zz.q' in 'window order by'",
        ),
        // The DML ORDER BY #0100's note leads with, in both statement forms
        // and with and without a LIMIT. `'order clause'`, measured — the
        // evaluator reported `'field list'` for the one shape that did reach
        // it, which was a row-bearing table and a WHERE that matched.
        (
            "UPDATE ClE SET k = 1 ORDER BY zz.q",
            1054,
            "Unknown column 'zz.q' in 'order clause'",
        ),
        (
            "UPDATE ClE SET k = 1 WHERE id = 4242 ORDER BY zz.q LIMIT 1",
            1054,
            "Unknown column 'zz.q' in 'order clause'",
        ),
        (
            "DELETE FROM ClE ORDER BY zz.q",
            1054,
            "Unknown column 'zz.q' in 'order clause'",
        ),
        (
            "DELETE FROM ClE WHERE id = 4242 ORDER BY zz.q LIMIT 1",
            1054,
            "Unknown column 'zz.q' in 'order clause'",
        ),
        // And what those clauses carry besides their names, which 8.3 settles
        // at the same moment.
        (
            "UPDATE ClE SET k = 1 ORDER BY s LIKE 'a' ESCAPE '!!'",
            1210,
            "Incorrect arguments to ESCAPE",
        ),
        (
            "DELETE FROM ClE ORDER BY SIGN()",
            1582,
            "Incorrect parameter count in the call to native function 'SIGN'",
        ),
        (
            "SELECT SUM(k) OVER (PARTITION BY s LIKE 'a' ESCAPE '!!') FROM ClE",
            1210,
            "Incorrect arguments to ESCAPE",
        ),
        (
            "SELECT ClE.k FROM ClE JOIN CrE ON ClE.s LIKE 'a' ESCAPE '!!'",
            1210,
            "Incorrect arguments to ESCAPE",
        ),
        // The ORDER BY is the last clause a DML statement settles, so anything
        // else wrong at the same time is named instead. 8.3's order, measured.
        (
            "UPDATE ClE SET k = zz.q ORDER BY yy.r",
            1054,
            "Unknown column 'zz.q' in 'field list'",
        ),
        (
            "UPDATE ClE SET k = 1 WHERE zz.q = 1 ORDER BY yy.r",
            1054,
            "Unknown column 'zz.q' in 'where clause'",
        ),
        // Within one clause 8.3 reads the list left to right and answers
        // whatever is wrong with the first item that is — a name or an
        // argument, whichever that item carries. Measured both ways for both
        // list clauses, over an empty table and over one with rows in it, and
        // the same answer each time. A pass that checked every name and then
        // every argument got the second of each pair wrong, and got it wrong
        // where the per-row path had it right.
        (
            "SELECT k FROM ClE GROUP BY nope, s LIKE 'a' ESCAPE '!!'",
            1054,
            "Unknown column 'nope' in 'group statement'",
        ),
        (
            "SELECT k FROM ClE GROUP BY s LIKE 'a' ESCAPE '!!', nope",
            1210,
            "Incorrect arguments to ESCAPE",
        ),
        (
            "UPDATE ClE SET k = 1 ORDER BY nope, s LIKE 'a' ESCAPE '!!'",
            1054,
            "Unknown column 'nope' in 'order clause'",
        ),
        (
            "UPDATE ClE SET k = 1 ORDER BY s LIKE 'a' ESCAPE '!!', nope",
            1210,
            "Incorrect arguments to ESCAPE",
        ),
        // An ON is one expression and not a list, so it cannot be read item by
        // item and one of the two orders has to be wrong. Arguments first is
        // right for three of the four 8.3 answers, and it is the order that
        // was already here — the name check was added behind it rather than
        // in front of it for exactly that reason.
        (
            "SELECT ClE.k FROM ClE JOIN CrE ON ClE.s LIKE 'a' ESCAPE '!!' AND nope = 1",
            1210,
            "Incorrect arguments to ESCAPE",
        ),
        (
            "SELECT ClE.k FROM ClE JOIN CrE ON SIGN() = 1 AND nope = 1",
            1582,
            "Incorrect parameter count in the call to native function 'SIGN'",
        ),
        (
            "SELECT ClE.k FROM ClE JOIN CrE ON nope = 1 AND SIGN() = 1",
            1582,
            "Incorrect parameter count in the call to native function 'SIGN'",
        ),
        // Reading the enclosing query's columns into the ON's scope must not
        // turn the check into one that accepts anything: a name in neither
        // scope is still refused, and still under the ON's own clause name.
        (
            "SELECT k FROM Seed WHERE EXISTS (SELECT 1 FROM ClE JOIN ClE c3 ON c3.id = Seed.zz)",
            1054,
            "Unknown column 'Seed.zz' in 'on clause'",
        ),
    ] {
        let err = refusal_of(&engine, &mut session, sql);
        assert_eq!(err.code, code, "for: {sql}");
        assert_eq!(err.message, message, "for: {sql}");
    }

    // The direction that matters more: nothing legal over the same empty
    // tables became an error. A resolver that refuses what MySQL answers turns
    // working SQL into a failure, which is worse than the silence it replaces.
    for sql in [
        "SELECT k AS a FROM ClE ORDER BY a",
        "SELECT k FROM ClE GROUP BY k",
        "SELECT ClE.k FROM ClE JOIN CrE ON ClE.id = CrE.id",
        "SELECT SUM(k) OVER (PARTITION BY k ORDER BY id) FROM ClE",
        "UPDATE ClE SET k = 1 ORDER BY id LIMIT 1",
        "DELETE FROM ClE ORDER BY id LIMIT 1",
        // An ON that correlates outwards names something that *is* in scope,
        // and the enclosing query's columns are not the join's — so resolving
        // one ahead of its first pair of rows has to read both, or an inner
        // side with no rows in it turns a query 8.3 answers into a 1054.
        // Measured there: both of these answer.
        //
        // Over `Seed`, which has the row: the subquery has to run for its join
        // to be built, and its own tables have to be empty for the resolver
        // rather than the evaluator to be what answers.
        "SELECT k FROM Seed WHERE EXISTS (SELECT 1 FROM ClE JOIN ClE c3 ON c3.id = Seed.id)",
        "SELECT k FROM Seed WHERE id IN (SELECT ClE.id FROM ClE JOIN CrE c2 ON Seed.id = c2.id)",
    ] {
        run(&engine, &mut session, sql);
    }
}

/// `ON DUPLICATE KEY UPDATE` resolves its names before anything collides.
///
/// The fifth entry point with #0009's recurring shape, and the one #0102 left
/// out: the clause is read only for a row that actually *does* collide, so on
/// an empty table, against a row with a different key, or on a table with no
/// unique key at all, nothing in it was resolved — `INSERT INTO Dup (id, k)
/// VALUES (1, 1) ON DUPLICATE KEY UPDATE k = a.b` inserted the row and
/// reported success where 8.3 raises 1054. "No collision" is this clause's
/// spelling of "no rows", so every refusal below is asserted over one.
///
/// The scope was measured rather than copied from the WHERE path, because
/// #0102's review had already shown what a wrong scope costs: it is the target
/// table's columns, `VALUES(x)` included and the insert's own column list
/// adding nothing to it. The `INSERT ... SELECT` and row-alias forms have a
/// *wider* scope on 8.3 and are left unresolved for that reason — they are in
/// the legal list below, where a guard that overreached would show up.
#[test]
fn on_duplicate_key_update_resolves_its_names_before_anything_collides() {
    let (engine, mut session) = engine();
    for ddl in [
        // Empty, which is the shape the hole hides in.
        "CREATE TABLE Dup (id INT NOT NULL, k INT NULL, s VARCHAR(20) NULL, PRIMARY KEY (id))",
        // One row, so the clause can be asked both with a collision and with
        // a key that misses one.
        "CREATE TABLE Hit (id INT NOT NULL, k INT NULL, PRIMARY KEY (id))",
        // No unique key at all, so nothing can ever collide here.
        "CREATE TABLE NoKey (a INT NULL, b INT NULL)",
        "CREATE TABLE Gen (id INT NOT NULL, k INT NULL, g INT AS (k + 1), PRIMARY KEY (id))",
        "CREATE TABLE Src (a INT NULL, b INT NULL)",
    ] {
        run(&engine, &mut session, ddl);
    }
    run(&engine, &mut session, "INSERT INTO Hit VALUES (1, 5)");
    run(&engine, &mut session, "INSERT INTO Src VALUES (7, 8)");

    // 8.3 names this clause `'field list'` for both halves of an assignment,
    // the same way it names a selected item's and an UPDATE's assigned value.
    for (sql, message) in [
        // The issue's own example, over the empty table.
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE k = a.b",
            "Unknown column 'a.b' in 'field list'",
        ),
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE k = nope",
            "Unknown column 'nope' in 'field list'",
        ),
        // `VALUES(x)` names a column of the target table, so an unknown one is
        // the same refusal — and the qualifier is compared rather than
        // dropped, as everywhere else a name is read here.
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE k = VALUES(nope)",
            "Unknown column 'nope' in 'field list'",
        ),
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE k = VALUES(a.b)",
            "Unknown column 'a.b' in 'field list'",
        ),
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE k = nodb.Dup.k",
            "Unknown column 'nodb.Dup.k' in 'field list'",
        ),
        // A row that exists and a key that does not meet it: the insert
        // succeeds, so the clause is never reached at all.
        (
            "INSERT INTO Hit (id, k) VALUES (2, 1) ON DUPLICATE KEY UPDATE k = nope",
            "Unknown column 'nope' in 'field list'",
        ),
        // A table with no unique key, where a collision is not merely absent
        // but impossible.
        (
            "INSERT INTO NoKey (a) VALUES (1) ON DUPLICATE KEY UPDATE b = nope",
            "Unknown column 'nope' in 'field list'",
        ),
        // A branch nothing takes, which is the rest of #0009's checklist: even
        // a collision would not evaluate this name.
        (
            "INSERT INTO Hit (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE \
             k = CASE WHEN 0 THEN nope ELSE 1 END",
            "Unknown column 'nope' in 'field list'",
        ),
        // And with a collision, where the evaluator would have reached the
        // name anyway — the case that always worked, kept so the guard is not
        // measured only by the rows it does not have.
        (
            "INSERT INTO Hit (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE k = nope",
            "Unknown column 'nope' in 'field list'",
        ),
        // The target half, which #0125 hoisted out of the collision branch
        // for this same reason. Here so a mutation to either line is caught.
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE nope = 1",
            "Unknown column 'nope' in 'field list'",
        ),
    ] {
        let err = refusal_of(&engine, &mut session, sql);
        assert_eq!(err.code, 1054, "expected ER_BAD_FIELD_ERROR for: {sql}");
        assert_eq!(err.message, message, "for: {sql}");
    }

    // The orderings, every one measured on 8.3. They are what makes this
    // worth more than a refusal each: the clause sits behind four of the
    // insert's own checks and in front of none of them.
    for (sql, code, why) in [
        (
            "INSERT INTO nosuch (k) VALUES (1) ON DUPLICATE KEY UPDATE k = nope",
            1146,
            "a missing table is answered before the clause is resolved",
        ),
        (
            "INSERT INTO Dup (nope2) VALUES (1) ON DUPLICATE KEY UPDATE k = nope",
            1054,
            "the insert's own column list resolves first",
        ),
        (
            "INSERT INTO Dup (id, k) VALUES (1) ON DUPLICATE KEY UPDATE k = nope",
            1136,
            "the value count is settled before the clause",
        ),
        (
            "INSERT INTO Gen (g) VALUES (1) ON DUPLICATE KEY UPDATE k = nope",
            3105,
            "a generated column in the insert list is settled before the clause",
        ),
        // The same two checks reached by their other road — a *later* value
        // list rather than the column list, which is where the engine settles
        // them for the statement rather than for a row.
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1), (2) ON DUPLICATE KEY UPDATE k = nope",
            1136,
            "a later row's value count is settled before the clause",
        ),
        (
            "INSERT INTO Gen VALUES (1, 1, 1) ON DUPLICATE KEY UPDATE k = nope",
            3105,
            "a written value for a generated column is settled before the clause",
        ),
        // 1582 comes out of 8.3's parser, so it precedes even a missing
        // table; the malformed ESCAPE does not. Both spellings measured.
        (
            "INSERT INTO nosuch (k) VALUES (1) ON DUPLICATE KEY UPDATE k = SIGN(1, 2)",
            1582,
            "1582 is raised in the parser, ahead of 1146",
        ),
        (
            "INSERT INTO nosuch (k) VALUES (1) ON DUPLICATE KEY UPDATE \
             k = ('a' LIKE 'b' ESCAPE '!!')",
            1146,
            "1210 is a resolve-time refusal, so 1146 comes first",
        ),
        // Within the clause: every target resolves before any value. This is
        // the opposite of the order the same pair settles in for an UPDATE,
        // which is why it had to be measured rather than reused.
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE k = nope2, nope1 = 1",
            1054,
            "the whole target list resolves before any value",
        ),
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE \
             nope1 = ('a' LIKE 'b' ESCAPE '!!')",
            1054,
            "an unknown target beats a malformed ESCAPE in its own value",
        ),
        // Among the values, the name and the ESCAPE interleave by position,
        // exactly as they do in a select list and in an UPDATE's SET: these
        // two differ only in the order of the assignments.
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE \
             k = ('a' LIKE 'b' ESCAPE '!!'), s = nope",
            1210,
            "the first assignment's problem wins",
        ),
        (
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE \
             k = nope, s = ('a' LIKE 'b' ESCAPE '!!')",
            1054,
            "the first assignment's problem wins",
        ),
    ] {
        let err = refusal_of(&engine, &mut session, sql);
        assert_eq!(err.code, code, "{why}, for: {sql}");
    }
    // Which name the first of those carries, not just that it refuses: a guard
    // that resolved the values before the targets would still answer 1054.
    assert_eq!(
        refusal_of(
            &engine,
            &mut session,
            "INSERT INTO Dup (id, k) VALUES (1, 1) ON DUPLICATE KEY UPDATE k = nope2, nope1 = 1",
        )
        .message,
        "Unknown column 'nope1' in 'field list'"
    );

    // Nothing legal now refuses, which is the direction #0102's review made
    // the point about — it caught `SET col = DEFAULT` being read as a column
    // called DEFAULT. Each id is its own, so none of these collides and the
    // table below says exactly which ones ran.
    for sql in [
        // A column of the table the insert did not name, bare and through
        // `VALUES()`: the insert's column list is not the scope.
        "INSERT INTO Dup (id, k) VALUES (11, 1) ON DUPLICATE KEY UPDATE s = s",
        "INSERT INTO Dup (id, k) VALUES (12, 1) ON DUPLICATE KEY UPDATE s = VALUES(s)",
        "INSERT INTO Dup (id, k) VALUES (13, 1) ON DUPLICATE KEY UPDATE k = VALUES(k)",
        "INSERT INTO Dup (id, k) VALUES (14, 1) ON DUPLICATE KEY UPDATE k = VALUES(Dup.k)",
        // The target table by name, by database and by back-quoted spelling.
        "INSERT INTO Dup (id, k) VALUES (15, 1) ON DUPLICATE KEY UPDATE k = Dup.k + 1",
        "INSERT INTO Dup (id, k) VALUES (16, 1) ON DUPLICATE KEY UPDATE k = testdb.Dup.k + 1",
        "INSERT INTO Dup (id, k) VALUES (17, 1) ON DUPLICATE KEY UPDATE Dup.k = 1",
        "INSERT INTO `Dup` (`id`, `k`) VALUES (18, 1) ON DUPLICATE KEY UPDATE `k` = `Dup`.`k`",
        // `DEFAULT` parses as a bare identifier and 8.3 accepts it here, so a
        // resolver that does not know the keyword refuses a legal statement.
        "INSERT INTO Dup (id, k) VALUES (19, 1) ON DUPLICATE KEY UPDATE k = DEFAULT",
        // A bare keyword that is an argument rather than a column, a variable,
        // and a subquery resolved in its own scope.
        "INSERT INTO Dup (id, k) VALUES (20, 1) ON DUPLICATE KEY UPDATE \
         k = TIMESTAMPDIFF(DAY, '2026-01-01', '2026-03-05')",
        "INSERT INTO Dup (id, k) VALUES (21, 1) ON DUPLICATE KEY UPDATE k = @v",
        "INSERT INTO Dup (id, k) VALUES (22, 1) ON DUPLICATE KEY UPDATE k = (SELECT MAX(a) FROM Src)",
        // The two forms whose scope is *wider* than the target table on 8.3,
        // and which this engine does not model: the clause of an `INSERT ...
        // SELECT` also sees the SELECT's FROM tables — `k = a` writes `Src`.`a`
        // there and `k = x.b` reads the alias — and the row alias form names
        // the row being inserted. Resolving either against the table alone
        // would refuse SQL 8.3 answers, so neither is resolved at all.
        "INSERT INTO Dup (id, k) SELECT a, b FROM Src x ON DUPLICATE KEY UPDATE k = x.b",
        "INSERT INTO Dup (id, k) SELECT a + 100, b FROM Src x ON DUPLICATE KEY UPDATE k = a",
        "INSERT INTO Dup (id, k) VALUES (23, 1) AS new ON DUPLICATE KEY UPDATE k = new.k",
    ] {
        run(&engine, &mut session, sql);
    }

    // Every refusal above stored nothing — 8.3 stores nothing for them either,
    // and a guard that refused after writing would show up here as an extra
    // row rather than as a failing assertion somewhere else.
    assert_eq!(
        rows(&engine, &mut session, "SELECT id FROM Dup ORDER BY id"),
        vec![
            vec!["7"],
            vec!["11"],
            vec!["12"],
            vec!["13"],
            vec!["14"],
            vec!["15"],
            vec!["16"],
            vec!["17"],
            vec!["18"],
            vec!["19"],
            vec!["20"],
            vec!["21"],
            vec!["22"],
            vec!["23"],
            vec!["107"],
        ]
    );
    assert_eq!(
        rows(&engine, &mut session, "SELECT id, k FROM Hit ORDER BY id"),
        vec![vec!["1", "5"]]
    );
    assert!(rows(&engine, &mut session, "SELECT a FROM NoKey").is_empty());

    // The clause still does what it is for: a collision updates the row that
    // was there, and `VALUES(x)` is the value the insert would have written.
    assert_eq!(
        affected(
            &engine,
            &mut session,
            "INSERT INTO Hit (id, k) VALUES (1, 9) ON DUPLICATE KEY UPDATE k = VALUES(k)",
        ),
        2
    );
    assert_eq!(
        rows(&engine, &mut session, "SELECT id, k FROM Hit ORDER BY id"),
        vec![vec!["1", "9"]]
    );
}

#[test]
fn a_self_join_update_counts_each_physical_row_once() {
    let (engine, mut session) = engine();
    run(
        &engine,
        &mut session,
        "CREATE TABLE S (id INTEGER NOT NULL, v INTEGER NOT NULL, PRIMARY KEY (id))",
    );
    run(&engine, &mut session, "INSERT INTO S VALUES (1, 1), (2, 2)");

    let updated = affected(
        &engine,
        &mut session,
        "UPDATE S x JOIN S y ON y.id = x.id SET x.v = 7",
    );
    assert_eq!(updated, 2, "two rows, not one per alias");
    assert_eq!(
        rows(&engine, &mut session, "SELECT v FROM S ORDER BY id"),
        vec![vec!["7"], vec!["7"]]
    );
}

#[test]
fn a_windowed_aggregate_with_order_by_runs_to_the_current_row() {
    // The default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW.
    // Folding the whole partition instead reports the final total on every
    // row, which is a different query than the one asked.
    let (engine, mut session) = engine();
    run(
        &engine,
        &mut session,
        "CREATE TABLE W (id INTEGER NOT NULL, g INTEGER NOT NULL, v INTEGER NOT NULL,
         PRIMARY KEY (id))",
    );
    run(
        &engine,
        &mut session,
        "INSERT INTO W VALUES (1, 1, 10), (2, 1, 20), (3, 2, 30)",
    );

    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT SUM(v) OVER (ORDER BY id) FROM W ORDER BY id"
        ),
        vec![vec!["10"], vec!["30"], vec!["60"]]
    );

    // In RANGE mode the current row means the last of its peer group, so tied
    // keys share one running total.
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT COUNT(*) OVER (ORDER BY g) FROM W ORDER BY id"
        ),
        vec![vec!["2"], vec!["2"], vec!["3"]]
    );

    // LAST_VALUE reads the end of that same frame.
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT LAST_VALUE(v) OVER (ORDER BY g) FROM W ORDER BY id"
        ),
        vec![vec!["20"], vec!["20"], vec!["30"]]
    );

    // Without ORDER BY the frame is the whole partition.
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT SUM(v) OVER (PARTITION BY g) FROM W ORDER BY id"
        ),
        vec![vec!["30"], vec!["30"], vec!["30"]]
    );
}

#[test]
fn a_negative_lag_offset_is_refused() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);

    let err = engine
        .execute(
            &mut session,
            "SELECT LAG(name, -1) OVER (ORDER BY id) FROM Widget",
            &[],
        )
        .unwrap_err();
    assert_eq!(err.code, 1210);
}

// --- Running the real migrations -------------------------------------------
//
// Everything below was found by pointing `prisma migrate deploy` at the engine
// and fixing whatever it hit next. Each is a feature the real 604-migration
// history needs, or a bug that history exposed.

#[test]
fn a_subquery_in_values_does_not_deadlock() {
    // The writer held the catalog's write lock while evaluating, and the
    // subquery needed a read lock to answer. `RwLock` is not reentrant, so the
    // statement hung forever rather than failing.
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);
    run(
        &engine,
        &mut session,
        "CREATE TABLE Pick (id VARCHAR(21) NOT NULL, chosen VARCHAR(120) NULL, PRIMARY KEY (id))",
    );

    run(
        &engine,
        &mut session,
        "INSERT INTO Pick (id, chosen) VALUES ('p1', (SELECT name FROM Widget WHERE id = 'a'))",
    );
    assert_eq!(
        rows(&engine, &mut session, "SELECT chosen FROM Pick"),
        vec![vec!["alpha"]]
    );

    // The same hazard on the UPDATE and DELETE paths.
    run(
        &engine,
        &mut session,
        "UPDATE Pick SET chosen = (SELECT name FROM Widget WHERE id = 'b')",
    );
    assert_eq!(
        rows(&engine, &mut session, "SELECT chosen FROM Pick"),
        vec![vec!["beta"]]
    );
    assert_eq!(
        affected(
            &engine,
            &mut session,
            "DELETE FROM Pick WHERE chosen = (SELECT name FROM Widget WHERE id = 'b')"
        ),
        1
    );
}

#[test]
fn insert_select_copies_rows() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);
    run(
        &engine,
        &mut session,
        "CREATE TABLE Copy (id VARCHAR(21) NOT NULL, name VARCHAR(120) NOT NULL, PRIMARY KEY (id))",
    );

    let inserted = affected(
        &engine,
        &mut session,
        "INSERT INTO Copy (id, name) SELECT id, name FROM Widget WHERE count > 1",
    );
    assert_eq!(inserted, 2);
    assert_eq!(
        rows(&engine, &mut session, "SELECT id FROM Copy ORDER BY id"),
        vec![vec!["a"], vec!["c"]]
    );

    // IGNORE still skips a duplicate rather than failing the statement.
    let again = affected(
        &engine,
        &mut session,
        "INSERT IGNORE INTO Copy (id, name) SELECT id, name FROM Widget",
    );
    assert_eq!(again, 1);
}

#[test]
fn a_multi_statement_command_runs_every_statement() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);

    let executed = engine.execute_many(
        &mut session,
        "UPDATE Widget SET count = 10 WHERE id = 'a'; \
         SELECT count FROM Widget WHERE id = 'a'; \
         DELETE FROM Widget WHERE id = 'b';",
        &[],
    );
    assert!(executed.error.is_none());
    assert_eq!(executed.outcomes.len(), 3);
    assert_eq!(
        rows(&engine, &mut session, "SELECT id FROM Widget ORDER BY id"),
        vec![vec!["a"], vec!["c"]]
    );
}

#[test]
fn a_semicolon_inside_a_literal_is_not_a_separator() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);

    let executed = engine.execute_many(
        &mut session,
        "UPDATE Widget SET note = 'a;b' WHERE id = 'a'; -- and a; comment\n\
         SELECT note FROM Widget WHERE id = 'a'",
        &[],
    );
    assert!(executed.error.is_none());
    assert_eq!(executed.outcomes.len(), 2);
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT note FROM Widget WHERE id = 'a'"
        ),
        vec![vec!["a;b"]]
    );
}

#[test]
fn a_multi_statement_command_stops_at_the_first_error() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);

    let executed = engine.execute_many(
        &mut session,
        "UPDATE Widget SET count = 5 WHERE id = 'a'; \
         SELECT * FROM Nope; \
         DELETE FROM Widget",
        &[],
    );
    assert!(executed.error.is_some());

    // The statement before the error stands; the one after it never ran.
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT count FROM Widget WHERE id = 'a'"
        ),
        vec![vec!["5"]]
    );
    assert_eq!(
        rows(&engine, &mut session, "SELECT id FROM Widget").len(),
        3
    );
}

#[test]
fn a_cte_can_be_selected_from_and_joined_to() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);

    assert_eq!(
        rows(
            &engine,
            &mut session,
            "WITH big AS (SELECT id, count FROM Widget WHERE count > 1) \
             SELECT id FROM big ORDER BY id"
        ),
        vec![vec!["a"], vec!["c"]]
    );

    // Named columns, and a join back to the base table.
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "WITH totals (wid, n) AS (SELECT id, count FROM Widget) \
             SELECT w.name, t.n FROM Widget w JOIN totals t ON t.wid = w.id \
             WHERE t.n = 3"
        ),
        vec![vec!["alpha", "3"]]
    );
}

#[test]
fn a_cte_can_feed_an_update() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);

    let updated = affected(
        &engine,
        &mut session,
        "WITH ranked AS (SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS rn FROM Widget) \
         UPDATE Widget w JOIN ranked r ON r.id = w.id SET w.count = r.rn",
    );
    assert_eq!(updated, 3);
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT count FROM Widget ORDER BY id"
        ),
        vec![vec!["1"], vec!["2"], vec!["3"]]
    );
}

#[test]
fn named_locks_are_held_per_connection() {
    // Prisma's migration engine takes GET_LOCK before it applies anything.
    let (engine, mut first) = engine();
    let mut second = Session::new(ServerConfig::default(), 2);
    second.current_database = Some("testdb".to_owned());

    assert_eq!(
        rows(&engine, &mut first, "SELECT GET_LOCK('m', 1)"),
        vec![vec!["1"]]
    );
    // Re-taking a lock this connection already holds succeeds; another
    // connection is told no rather than waiting for a holder in the same
    // process that cannot release while it waits.
    assert_eq!(
        rows(&engine, &mut first, "SELECT GET_LOCK('m', 1)"),
        vec![vec!["1"]]
    );
    assert_eq!(
        rows(&engine, &mut second, "SELECT GET_LOCK('m', 1)"),
        vec![vec!["0"]]
    );
    assert_eq!(
        rows(&engine, &mut second, "SELECT IS_USED_LOCK('m')"),
        vec![vec!["1"]]
    );

    // Releasing someone else's lock reports 0 and does not release it.
    assert_eq!(
        rows(&engine, &mut second, "SELECT RELEASE_LOCK('m')"),
        vec![vec!["0"]]
    );
    assert_eq!(
        rows(&engine, &mut first, "SELECT RELEASE_LOCK('m')"),
        vec![vec!["1"]]
    );
    assert_eq!(
        rows(&engine, &mut second, "SELECT IS_FREE_LOCK('m')"),
        vec![vec!["1"]]
    );
    // An unheld lock releases to NULL, not 0.
    assert_eq!(
        rows(&engine, &mut first, "SELECT RELEASE_LOCK('m')"),
        vec![vec!["NULL"]]
    );
}

#[test]
fn generated_values_are_unique_and_deterministic() {
    let (first_engine, mut second_session) = engine();
    let (engine, session) = (&first_engine, &mut second_session);

    let first = rows(engine, session, "SELECT UUID(), UUID(), MD5('abc')");
    // Two calls in one statement must not collide, and neither must their
    // prefixes: the migrations derive ids with SUBSTRING(REPLACE(UUID(), ...)).
    assert_ne!(first[0][0], first[0][1]);
    assert_ne!(first[0][0][..8], first[0][1][..8]);
    assert_eq!(first[0][2], "900150983cd24fb0d6963f7d28e17f72");

    // A fresh engine repeats the sequence, so a test can assert on an id.
    let (other, mut other_session) = fresh_engine();
    assert_eq!(
        rows(&other, &mut other_session, "SELECT UUID()")[0][0],
        first[0][0]
    );

    // RAND stays inside [0, 1) and moves.
    let r = rows(engine, session, "SELECT RAND(), RAND()");
    let (a, b): (f64, f64) = (r[0][0].parse().unwrap(), r[0][1].parse().unwrap());
    assert!((0.0..1.0).contains(&a) && (0.0..1.0).contains(&b));
    assert_ne!(a, b);
}

#[test]
fn regular_expressions_match_and_replace() {
    let (engine, mut session) = engine();
    widgets(&engine, &mut session);

    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT REGEXP_REPLACE('Hello World', '[^a-zA-Z]+', '-')"
        ),
        vec![vec!["Hello-World"]]
    );
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT id FROM Widget WHERE name REGEXP '^(al|ga)' ORDER BY id"
        ),
        vec![vec!["a"], vec!["c"]]
    );
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT id FROM Widget WHERE name NOT REGEXP '^(al|ga)'"
        ),
        vec![vec!["b"]]
    );
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT REGEXP_SUBSTR('a1b22c', '[0-9]+')"
        ),
        vec![vec!["1"]]
    );
    assert_eq!(
        rows(
            &engine,
            &mut session,
            "SELECT REGEXP_INSTR('a1b22c', '[0-9]{2}')"
        ),
        vec![vec!["4"]]
    );

    // A pattern the engine cannot compile is an error, never a silent no-match
    // that would rewrite or skip the wrong rows.
    let err = engine
        .execute(&mut session, "SELECT REGEXP_LIKE('a', '[')", &[])
        .unwrap_err();
    assert_eq!(err.code, 3692);
}

